export type Todo = {
  id: string
  text: string
  done: boolean
}

export type Filter = 'all' | 'active' | 'done'

export type Action =
  | { type: 'add'; id: string; text: string }
  | { type: 'toggle'; id: string }
  | { type: 'toggleAll' }
  | { type: 'edit'; id: string; text: string }
  | { type: 'remove'; id: string }
  | { type: 'clearDone' }

export function todosReducer(todos: Todo[], action: Action): Todo[] {
  switch (action.type) {
    case 'add': {
      const text = action.text.trim()
      return text ? [...todos, { id: action.id, text, done: false }] : todos
    }
    case 'toggle':
      return todos.map((t) => (t.id === action.id ? { ...t, done: !t.done } : t))
    case 'toggleAll': {
      const allDone = todos.length > 0 && todos.every((t) => t.done)
      return todos.map((t) => ({ ...t, done: !allDone }))
    }
    case 'edit': {
      const text = action.text.trim()
      // Clearing the text of an existing todo deletes it.
      if (!text) return todos.filter((t) => t.id !== action.id)
      return todos.map((t) => (t.id === action.id ? { ...t, text } : t))
    }
    case 'remove':
      return todos.filter((t) => t.id !== action.id)
    case 'clearDone':
      return todos.filter((t) => !t.done)
  }
}

export function filterTodos(todos: Todo[], filter: Filter): Todo[] {
  if (filter === 'active') return todos.filter((t) => !t.done)
  if (filter === 'done') return todos.filter((t) => t.done)
  return todos
}

const STORAGE_KEY = 'react-todo:v1'

function isTodo(value: unknown): value is Todo {
  if (typeof value !== 'object' || value === null) return false
  const v = value as Record<string, unknown>
  return typeof v.id === 'string' && typeof v.text === 'string' && typeof v.done === 'boolean'
}

/** Reads saved todos; anything missing, corrupt or blocked yields an empty list. */
export function loadTodos(): Todo[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return []
    const parsed: unknown = JSON.parse(raw)
    return Array.isArray(parsed) ? parsed.filter(isTodo) : []
  } catch {
    return []
  }
}

/** Best-effort save: storage can be full or disabled (private mode), which must not break the app. */
export function saveTodos(todos: Todo[]): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos))
  } catch {
    // ignore
  }
}

/** crypto.randomUUID only exists in secure contexts, so fall back for plain-http LAN use. */
export function newId(): string {
  return typeof crypto.randomUUID === 'function'
    ? crypto.randomUUID()
    : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`
}

